                    type="category"
                    dataKey="label"
                    width={110}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip />
                  <Bar dataKey="kw" name="kW / EV" fill={TEAL} radius={[0, 4, 4, 0]}>
                    {kwBars.map((d) => (
                      <Cell
                        key={d.id}
