                    fillOpacity={0.25}
                    strokeWidth={2}
                  />
                  <Line
                    type="monotone"
                    dataKey="EU fast+ultra"
                    stroke={INDIGO}
                    strokeWidth={2}
                    dot={false}
                  />
                  <Line
                    type="monotone"
                    dataKey="United States"
                    stroke={ROSE}
                    strokeWidth={2.5}
                    dot={false}
                  />
                  <Line
                    type="monotone"
                    dataKey="Korea"
                    stroke={AMBER}
                    strokeWidth={2}
                    dot={false}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
